ruleBookInfo.tocUrl:
@js:
var cdkey = source.get("cdkey");
var bid = java.get("myBookId");
'http://101.200.42.234:15384/fq/getcatalog?bookId=' + bid + '&token=' + cdkey;

ruleSearch.bookUrl:
@js:
var cdkey = source.get("cdkey");
var bid = String(java.getString("$.bookId"));
java.put("myBookId", bid);
'http://101.200.42.234:15384/fq/searchbook?keyword=' + bid + '&token=' + cdkey;

ruleToc.chapterUrl:
@js:
var cdkey = source.get("cdkey");
var bid = java.get("myBookId");
'http://101.200.42.234:15384/fq/getchapter?bookId=' + bid + '&chapterId=' + java.getString("$.chapterId") + '&token=' + cdkey;
